import { defineExperience, startExperience } from "@signal-lab/experience-sdk";
import { createWindScene, type WindScene } from "./scene";
import { directWindStory } from "./director";

let scene: WindScene | null = null;
let root: HTMLElement | null = null;
let environmentImage: HTMLImageElement | null = null;
let imageErrorHandler: (() => void) | null = null;

function buildPage(container: HTMLElement): HTMLElement {
  const page = document.createElement("main");
  page.className = "wind-page";
  page.setAttribute("aria-label", "读取今夜的风");
  page.innerHTML = `
    <div class="environment" aria-hidden="true">
      <img class="environment__image" src="/creative-assets/r16-night-wind-instrument-v1.png" alt="" />
      <div class="environment__veil"></div>
      <div class="window-slit"></div>
    </div>
    <nav class="quiet-nav" aria-label="页面导航">
      <a href="#opening" class="quiet-nav__mark">夜风谱</a>
      <a href="#reading">观测证据</a>
      <a href="#resolve">今夜读数</a>
    </nav>
    <div class="story">
      <section class="opening" id="opening">
        <p class="eyebrow">窗边气象装置 · 21:40</p>
        <h1>风经过房间之前，<br />先留下形状。</h1>
        <p class="lede">月白陶瓷收住室内的静，氧化铜与细纤维把窗外看不见的流动，变成能够停留片刻的证据。</p>
        <a class="text-link" href="#reading">沿窗缝向外看 <span aria-hidden="true">↓</span></a>
      </section>

      <section class="evidence" id="reading" aria-labelledby="reading-title">
        <div class="evidence__copy">
          <p class="eyebrow">气流经过窗缝</p>
          <h2 id="reading-title">不是数字先抵达，<br />是纤维先弯曲。</h2>
          <p>不同风速改变纤维的弧度；温度、湿度与方向沿同一条气流轨迹显影。读数因此有了来处，也有了方向。</p>
        </div>
        <dl class="readings" aria-label="今夜环境证据">
          <div><dt>风向</dt><dd>东南偏东</dd></div>
          <div><dt>温度</dt><dd>22.8°C</dd></div>
          <div><dt>湿度</dt><dd>67%</dd></div>
          <div><dt>风速</dt><dd>1.6 m/s</dd></div>
        </dl>
      </section>

      <section class="resolve" id="resolve" aria-labelledby="resolve-title">
        <div class="resolve__panel">
          <p class="eyebrow">窗边 · 稳定观测</p>
          <h2 id="resolve-title">读取今夜的风</h2>
          <p>让窗外的自然节律，成为房间里一件安静、可信的日常事物。</p>
          <button class="primary-action" type="button">开始今夜读取</button>
          <p class="status" aria-live="polite">装置已就绪 · 纤维处于低风速状态</p>
        </div>
      </section>
    </div>`;
  container.appendChild(page);
  return page;
}

startExperience(defineExperience({
  mount(context) {
    root = buildPage(context.container);
    environmentImage = root.querySelector<HTMLImageElement>(".environment__image");
    imageErrorHandler = () => root?.classList.add("asset-fallback");
    environmentImage?.addEventListener("error", imageErrorHandler);

    const action = root.querySelector<HTMLButtonElement>(".primary-action");
    action?.addEventListener("click", () => {
      const status = root?.querySelector<HTMLElement>(".status");
      if (status) status.textContent = "正在读取 · 请留意纤维方向的缓慢变化";
    });

    try {
      scene = createWindScene(context.canvas, context.viewport, context.quality, context.reducedMotion);
    } catch {
      root.classList.add("webgl-fallback");
      scene = null;
    }
  },

  update(frame) {
    if (!root) return;
    const state = directWindStory(frame.progress, frame.pointer, frame.elapsed, frame.reducedMotion);
    root.style.setProperty("--clarity", state.environmentClarity.toFixed(3));
    root.style.setProperty("--veil", state.veilOpacity.toFixed(3));
    root.style.setProperty("--slit", state.slitPresence.toFixed(3));
    root.dataset.phase = state.phase;
    scene?.render(state, frame.delta);
  },

  resize(viewport) {
    scene?.resize(viewport);
  },

  dispose() {
    if (environmentImage && imageErrorHandler) {
      environmentImage.removeEventListener("error", imageErrorHandler);
    }
    scene?.dispose();
    scene = null;
    environmentImage = null;
    imageErrorHandler = null;
    root?.remove();
    root = null;
  }
}));

export type WindPhase = "haze" | "crossing" | "record";

export interface WindStoryState {
  phase: WindPhase;
  cameraX: number;
  cameraY: number;
  cameraZ: number;
  lookX: number;
  fiberBend: number;
  evidenceProgress: number;
  evidenceVisibility: number;
  environmentClarity: number;
  veilOpacity: number;
  slitPresence: number;
  copperWarmth: number;
}

interface PointerState {
  x: number;
  y: number;
}

const clamp01 = (value: number): number => Math.min(1, Math.max(0, value));
const smooth = (a: number, b: number, value: number): number => {
  const t = clamp01((value - a) / (b - a));
  return t * t * (3 - 2 * t);
};

export function directWindStory(
  progress: number,
  pointer: PointerState,
  elapsed: number,
  reducedMotion: boolean
): WindStoryState {
  const p = clamp01(progress);
  const crossing = smooth(0.16, 0.58, p);
  const returning = smooth(0.67, 0.92, p);
  const resolve = smooth(0.78, 0.96, p);
  const phase: WindPhase = p < 0.25 ? "haze" : p < 0.78 ? "crossing" : "record";

  if (reducedMotion) {
    const stable = p < 0.34 ? 0 : p < 0.72 ? 0.55 : 1;
    return {
      phase,
      cameraX: stable === 0.55 ? 0.42 : 0,
      cameraY: 0.08,
      cameraZ: stable === 0.55 ? 4.45 : 5.4,
      lookX: stable === 0.55 ? 0.34 : 0,
      fiberBend: stable === 0 ? 0.08 : stable === 0.55 ? 0.72 : 0.34,
      evidenceProgress: stable,
      evidenceVisibility: stable === 0.55 ? 1 : stable,
      environmentClarity: stable === 0 ? 0.4 : stable === 0.55 ? 0.78 : 1,
      veilOpacity: stable === 0 ? 0.62 : stable === 0.55 ? 0.28 : 0.12,
      slitPresence: stable === 0.55 ? 1 : 0.16,
      copperWarmth: stable
    };
  }

  const restrainedBreath = phase === "record" ? 0 : Math.sin(elapsed * 0.42) * 0.018;
  const parallaxX = pointer.x * 0.055;
  const parallaxY = pointer.y * 0.035;
  const outward = crossing * (1 - returning);

  return {
    phase,
    cameraX: outward * 0.74 + parallaxX,
    cameraY: 0.08 + parallaxY + restrainedBreath,
    cameraZ: 5.45 - outward * 1.62,
    lookX: outward * 0.5,
    fiberBend: 0.08 + smooth(0.25, 0.6, p) * 0.92 - returning * 0.62,
    evidenceProgress: smooth(0.34, 0.74, p),
    evidenceVisibility: smooth(0.3, 0.46, p) * (1 - smooth(0.79, 0.94, p)),
    environmentClarity: 0.35 + smooth(0.04, 0.58, p) * 0.65,
    veilOpacity: 0.66 - smooth(0.03, 0.62, p) * 0.48 - resolve * 0.08,
    slitPresence: 0.12 + outward * 0.88,
    copperWarmth: smooth(0.48, 0.95, p)
  };
}

import * as THREE from "three";
import type { WindStoryState } from "./director";

interface Viewport {
  width: number;
  height: number;
  dpr: number;
}

export interface WindScene {
  render(state: WindStoryState, delta: number): void;
  resize(viewport: Viewport): void;
  dispose(): void;
}

interface Fiber {
  line: THREE.Line<THREE.BufferGeometry, THREE.LineBasicMaterial>;
  positions: Float32Array;
  rootX: number;
  length: number;
  phase: number;
}

function makeRingMaterial(color: number): THREE.MeshBasicMaterial {
  return new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0, depthWrite: false });
}

export function createWindScene(
  canvas: HTMLCanvasElement,
  viewport: Viewport,
  quality: string,
  reducedMotion: boolean
): WindScene {
  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: quality !== "low", powerPreference: "high-performance" });
  renderer.setClearColor(0x000000, 0);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.setPixelRatio(Math.min(viewport.dpr, quality === "low" ? 1.25 : 2));
  renderer.setSize(viewport.width, viewport.height, false);

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(34, viewport.width / Math.max(1, viewport.height), 0.1, 30);
  camera.position.set(0, 0.08, 5.45);

  const device = new THREE.Group();
  device.position.set(0.68, -0.5, 0);
  scene.add(device);

  const ceramic = new THREE.MeshStandardMaterial({ color: 0xe6e1d5, roughness: 0.82, metalness: 0.02 });
  const copper = new THREE.MeshStandardMaterial({ color: 0x76503c, roughness: 0.58, metalness: 0.42 });
  const baseGeometry = new THREE.CylinderGeometry(0.62, 0.72, 0.2, quality === "low" ? 32 : 64);
  const base = new THREE.Mesh(baseGeometry, ceramic);
  base.position.y = -0.56;
  device.add(base);

  const arcGeometry = new THREE.TorusGeometry(0.58, 0.035, quality === "low" ? 8 : 14, quality === "low" ? 44 : 80, Math.PI * 1.52);
  const arc = new THREE.Mesh(arcGeometry, copper);
  arc.rotation.z = -Math.PI * 0.76;
  arc.position.y = 0.06;
  device.add(arc);

  const ambient = new THREE.HemisphereLight(0xeae5d8, 0x3a3731, 1.35);
  const moon = new THREE.DirectionalLight(0xf1eee4, 2.1);
  moon.position.set(-3, 4, 5);
  scene.add(ambient, moon);

  const fiberCount = quality === "low" ? 9 : 15;
  const fiberSegments = quality === "low" ? 16 : 24;
  const fibers: Fiber[] = [];
  const fiberMaterial = new THREE.LineBasicMaterial({ color: 0xcac4b7, transparent: true, opacity: 0.72 });
  for (let index = 0; index < fiberCount; index += 1) {
    const positions = new Float32Array((fiberSegments + 1) * 3);
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const line = new THREE.Line(geometry, fiberMaterial.clone());
    line.position.set(0.68, -0.38, 0.02 + (index % 3) * 0.012);
    scene.add(line);
    fibers.push({
      line,
      positions,
      rootX: -0.45 + (index / Math.max(1, fiberCount - 1)) * 0.9,
      length: 0.72 + (index % 4) * 0.045,
      phase: index * 0.61
    });
  }

  const evidenceGroup = new THREE.Group();
  evidenceGroup.position.set(-0.9, 0.18, 0.16);
  scene.add(evidenceGroup);
  const ringGeometry = new THREE.RingGeometry(0.055, 0.071, 32);
  const evidenceColors = [0xb18465, 0xd7d2c5, 0x9a765f];
  const evidence = evidenceColors.map((color, index) => {
    const ring = new THREE.Mesh(ringGeometry, makeRingMaterial(color));
    ring.position.z = index * 0.02;
    evidenceGroup.add(ring);
    return ring;
  });

  const aim = new THREE.Vector3();
  const tempColor = new THREE.Color();
  let smoothedBend = 0.08;

  function updateFibers(bend: number, elapsedDelta: number): void {
    smoothedBend += (bend - smoothedBend) * Math.min(1, elapsedDelta * (reducedMotion ? 10 : 4.5));
    for (let f = 0; f < fibers.length; f += 1) {
      const fiber = fibers[f];
      for (let point = 0; point <= fiberSegments; point += 1) {
        const t = point / fiberSegments;
        const offset = point * 3;
        fiber.positions[offset] = fiber.rootX + smoothedBend * t * t * (0.42 + f * 0.006);
        fiber.positions[offset + 1] = t * fiber.length;
        fiber.positions[offset + 2] = Math.sin(t * Math.PI + fiber.phase) * smoothedBend * 0.035 * t;
      }
      const attribute = fiber.line.geometry.getAttribute("position");
      attribute.needsUpdate = true;
    }
  }

  function updateEvidence(state: WindStoryState): void {
    for (let index = 0; index < evidence.length; index += 1) {
      const local = Math.min(1, Math.max(0, state.evidenceProgress * 1.45 - index * 0.2));
      const ring = evidence[index];
      ring.position.x = local * 2.2;
      ring.position.y = Math.sin(local * Math.PI) * (0.22 + index * 0.06) - index * 0.12;
      ring.scale.setScalar(0.78 + local * 0.34);
      const material = ring.material;
      if (Array.isArray(material)) {
        for (const item of material) {
          item.transparent = true;
          item.opacity = state.evidenceVisibility * (0.5 + local * 0.45);
        }
      } else {
        material.transparent = true;
        material.opacity = state.evidenceVisibility * (0.5 + local * 0.45);
      }
    }
  }

  return {
    render(state, delta) {
      camera.position.set(state.cameraX, state.cameraY, state.cameraZ);
      aim.set(state.lookX, -0.02, 0);
      camera.lookAt(aim);
      updateFibers(state.fiberBend, Math.max(0, Math.min(delta, 0.1)));
      updateEvidence(state);
      tempColor.setRGB(0.46 + state.copperWarmth * 0.09, 0.31 + state.copperWarmth * 0.035, 0.23);
      copper.color.copy(tempColor);
      renderer.render(scene, camera);
    },

    resize(nextViewport) {
      camera.aspect = nextViewport.width / Math.max(1, nextViewport.height);
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(nextViewport.dpr, quality === "low" ? 1.25 : 2));
      renderer.setSize(nextViewport.width, nextViewport.height, false);
    },

    dispose() {
      scene.traverse((object) => {
        if (!(object instanceof THREE.Mesh) && !(object instanceof THREE.Line)) return;
        object.geometry.dispose();
        const material = object.material;
        if (Array.isArray(material)) {
          for (const item of material) item.dispose();
        } else {
          material.dispose();
        }
      });
      renderer.dispose();
    }
  };
}

*, *::before, *::after { box-sizing: border-box; }
html { margin: 0; scroll-behavior: smooth; background: #272623; }
body { margin: 0; max-width: 100%; overflow-x: clip; color: #f2f0e8; background: #272623; font-family: "Noto Serif SC", "Songti SC", Georgia, serif; }
button, a { font: inherit; }
a { color: inherit; }
canvas {
  position: fixed;
  z-index: 1;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.wind-page {
  --clarity: .35;
  --veil: .66;
  --slit: .12;
  position: relative;
  min-height: 300vh;
  max-width: 100%;
  background: transparent;
}

.environment, .environment__image, .environment__veil, .window-slit {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.environment { z-index: 0; overflow: hidden; background: radial-gradient(circle at 68% 48%, #77766f 0%, #4a4944 45%, #292825 100%); }
.environment__image {
  object-fit: cover;
  object-position: center;
  filter: grayscale(.18) sepia(.12) contrast(calc(.78 + var(--clarity) * .2)) brightness(calc(.55 + var(--clarity) * .25)) blur(calc((1 - var(--clarity)) * 5px));
  transform: scale(calc(1.035 - var(--clarity) * .02));
  opacity: .94;
  transition: filter 120ms linear;
}
.environment__veil {
  background: linear-gradient(90deg, rgba(31,30,28,.74) 0%, rgba(39,38,35,.25) 48%, rgba(30,29,27,.5) 100%), radial-gradient(circle at 64% 47%, transparent 15%, rgba(30,29,27,var(--veil)) 88%);
}
.window-slit {
  left: auto;
  right: 18%;
  width: clamp(2px, calc(var(--slit) * 4vw), 46px);
  background: linear-gradient(90deg, transparent, rgba(231,226,211,.18), transparent);
  opacity: var(--slit);
  filter: blur(7px);
}
.asset-fallback .environment__image { display: none; }
.asset-fallback .environment { background: radial-gradient(ellipse at 70% 46%, #8a8980 0%, #55534d 29%, #302f2b 72%); }

.quiet-nav {
  position: fixed;
  z-index: 5;
  inset: 0 0 auto 0;
  display: flex;
  align-items: center;
  gap: clamp(18px, 3vw, 44px);
  padding: 24px clamp(20px, 5vw, 72px);
  font-family: system-ui, sans-serif;
  font-size: 11px;
  letter-spacing: .13em;
  color: rgba(242,240,232,.72);
}
.quiet-nav a { text-decoration: none; }
.quiet-nav__mark { margin-right: auto; color: #f2f0e8; }

.story { position: relative; z-index: 2; min-height: 300vh; }
.story section { width: 100%; max-width: 100%; }
.opening {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  padding: 15vh clamp(22px, 7vw, 108px) 10vh;
}
.eyebrow {
  margin: 0 0 18px;
  color: #c7b7a6;
  font: 500 11px/1.5 system-ui, sans-serif;
  letter-spacing: .18em;
  text-transform: uppercase;
}
h1, h2 { margin: 0; font-weight: 450; letter-spacing: -.045em; text-wrap: balance; }
h1 { max-width: 780px; font-size: clamp(42px, 6.4vw, 88px); line-height: 1.08; }
h2 { font-size: clamp(34px, 4.8vw, 68px); line-height: 1.13; }
.lede, .evidence__copy > p:last-child, .resolve__panel > p:not(.eyebrow):not(.status) {
  max-width: 560px;
  margin: 28px 0 0;
  color: rgba(242,240,232,.76);
  font-size: clamp(15px, 1.35vw, 18px);
  line-height: 1.9;
}
.text-link { margin-top: 32px; font: 500 13px/1.4 system-ui, sans-serif; letter-spacing: .08em; text-decoration: none; border-bottom: 1px solid rgba(242,240,232,.48); padding-bottom: 8px; }

.evidence {
  min-height: 105vh;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(260px, .55fr);
  align-items: center;
  gap: clamp(40px, 9vw, 160px);
  padding: 14vh clamp(22px, 7vw, 108px);
}
.evidence__copy { max-width: 620px; }
.readings { margin: 0; padding: 0; border-top: 1px solid rgba(242,240,232,.3); font-family: system-ui, sans-serif; }
.readings div { display: flex; justify-content: space-between; gap: 24px; padding: 17px 0; border-bottom: 1px solid rgba(242,240,232,.18); }
.readings dt { color: rgba(242,240,232,.6); font-size: 12px; letter-spacing: .12em; }
.readings dd { margin: 0; color: #eee9dc; font-size: 14px; font-variant-numeric: tabular-nums; }

.resolve {
  min-height: 95vh;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 13vh clamp(22px, 8vw, 124px);
  background: linear-gradient(90deg, transparent 28%, rgba(34,33,30,.18) 56%, rgba(30,29,27,.72) 100%);
}
.resolve__panel { width: min(520px, 100%); padding: clamp(24px, 3vw, 42px) 0; background: transparent; border: 0; text-shadow: 0 2px 26px rgba(20,19,17,.72); }
.primary-action { margin-top: 34px; min-height: 48px; padding: 13px 24px; color: #292723; background: #ded8ca; border: 0; border-radius: 2px; cursor: pointer; font: 600 14px/1.2 system-ui, sans-serif; letter-spacing: .08em; }
.primary-action:focus-visible, .quiet-nav a:focus-visible, .text-link:focus-visible { outline: 2px solid #e7dfcf; outline-offset: 5px; }
.status { margin: 18px 0 0; color: rgba(242,240,232,.56); font: 11px/1.5 system-ui, sans-serif; letter-spacing: .08em; }

.webgl-fallback .resolve { background: linear-gradient(90deg, transparent 24%, rgba(34,33,30,.3) 54%, rgba(30,29,27,.9) 100%); }

@media (max-width: 720px) {
  .wind-page, .story { min-height: 315vh; }
  .quiet-nav { padding: 18px 20px; }
  .quiet-nav a:not(.quiet-nav__mark) { display: none; }
  .opening { min-height: 105vh; padding: 16vh 22px 12vh; justify-content: flex-start; }
  h1 { max-width: 100%; font-size: clamp(38px, 12vw, 58px); line-height: 1.1; }
  h2 { font-size: clamp(32px, 9vw, 48px); }
  .lede { margin-top: 22px; max-width: 92%; font-size: 15px; line-height: 1.75; }
  .text-link { margin-top: 25px; }
  .evidence { min-height: 110vh; grid-template-columns: 1fr; align-content: center; gap: 42px; padding: 12vh 22px; }
  .readings { width: 100%; }
  .resolve { min-height: 100vh; align-items: flex-end; padding: 16vh 22px 8vh; background: linear-gradient(180deg, transparent 24%, rgba(31,30,27,.34) 58%, rgba(27,26,24,.9) 100%); }
  .resolve__panel { padding: 28px 0; }
  .window-slit { right: 10%; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .environment__image { transition: opacity .25s ease; transform: none; }
}
